        if (guests < 1) {
            throw new IllegalArgumentException("INVALID_REQUEST");
        }
        if (guests > capacity) {
            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
        }
        if (checkOut.compareTo(checkIn) <= 0) {
            throw new IllegalArgumentException("INVALID_REQUEST");
