            if (companyCode == null || (!companyCode.equals("TECNOSUL") && 
                !companyCode.equals("AGROVALE") && !companyCode.equals("FARMAVIDA"))) {
                throw new IllegalArgumentException("INVALID_REQUEST");
            }
