        if (ratePlan.equals("WEEKEND_PACKAGE")) {
            validateWeekendPackage(checkIn, checkOut);
        }

        if (ratePlan.equals("LONG_STAY")) {
            int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
