        app.get("/messages", MessageHandler::list);

        app.get("/reports/occupancy", ReportHandler::occupancy);
        app.get("/reports/revenue", ReportHandler::revenue);

        app.exception(Exception.class, (e, ctx) -> {
            ctx.status(500);
        });
    }
}

